package vn.eduassistant.backend.web;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import vn.eduassistant.backend.core.ApiResponse;
import vn.eduassistant.backend.core.Json;
import vn.eduassistant.backend.db.JdbcSupport;
import vn.eduassistant.backend.service.*;
import javax.servlet.http.HttpServletRequest;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;

@RestController
public class EvidenceController {
    private final AuthService auth;private final UploadService upload;private final OcrService ocr;private final JdbcSupport db;private final CaseService cases;private final UserService users;private final AuditService audits;
    public EvidenceController(AuthService auth,UploadService upload,OcrService ocr,JdbcSupport db,CaseService cases,UserService users,AuditService audits){this.auth=auth;this.upload=upload;this.ocr=ocr;this.db=db;this.cases=cases;this.users=users;this.audits=audits;}
    @PostMapping("/api/upload/evidence-ocr") public ResponseEntity<?> uploadOcr(@RequestParam("evidence")MultipartFile file,HttpServletRequest req){return uploadFile(file,req);}
    @PostMapping("/api/upload/evidence") public ResponseEntity<?> upload(@RequestParam("evidence")MultipartFile file,HttpServletRequest req){return uploadFile(file,req);}
    private ResponseEntity<?> uploadFile(MultipartFile file,HttpServletRequest req){Map<String,Object>u=auth.currentUser(req);try{if(file.getSize()>UploadService.MAX_SIZE)return ApiResponse.failure(413,false,"Tệp vượt quá giới hạn 10 MB.",null,"FILE_TOO_LARGE");byte[]bytes=file.getBytes();if(bytes.length>UploadService.MAX_SIZE)return ApiResponse.failure(413,false,"Tệp vượt quá giới hạn 10 MB.",null,"FILE_TOO_LARGE");Map<String,Object>saved=upload.saveEvidence(bytes,first(file.getOriginalFilename(),"evidence_file"),u),ocrResult=ocr.extract(bytes,first(file.getOriginalFilename(),"evidence_file"));Map<String,Object>ocrData=Json.object(ocrResult.get("data"));String name=Json.str(saved.get("fileName")),now=Instant.now().toString();db.update("INSERT INTO evidence_uploads(filename,ownerid,metadata,ocrdata,ocrprovider,ocrislive,createdat) VALUES(?,?,?,?,?,?,?) ON CONFLICT(filename) DO UPDATE SET metadata=EXCLUDED.metadata,ocrdata=EXCLUDED.ocrdata,ocrprovider=EXCLUDED.ocrprovider,ocrislive=EXCLUDED.ocrislive WHERE evidence_uploads.ownerid=EXCLUDED.ownerid",name,u.get("id"),Json.stringify(saved.get("metadata")),Json.stringify(ocrData),ocrResult.get("provider"),Json.bool(ocrResult.get("isLive")),now);saved.put("ocrData",ocrData);saved.put("ocrProvider",ocrResult.get("provider"));saved.put("ocrModel",ocrResult.get("model"));saved.put("ocrIsLive",Json.bool(ocrResult.get("isLive")));saved.put("modeUsed",ocrResult.get("modeUsed"));saved.put("isFallback",ocrResult.get("isFallback"));saved.put("isSynthetic",ocrResult.get("isSynthetic"));saved.put("apiCallPerformed",ocrResult.get("apiCallPerformed"));saved.put("apiAttempts",ocrResult.get("apiAttempts"));saved.put("ocrDurationMs",ocrResult.get("durationMs"));Map<String,Object>out=new LinkedHashMap<String,Object>();out.put("file",saved);out.put("ocr",ocrResult);out.putAll(saved);String message="Tải tệp minh chứng thành công.";if(!Json.bool(ocrResult.get("success")))message+=" Không trích xuất được OCR; hệ thống không tự điền thông tin suy đoán.";audits.log("EVIDENCE_UPLOADED",u,UserService.map("originalName",file.getOriginalFilename(),"originalSize",bytes.length),"SUCCESS","Tải lên minh chứng "+file.getOriginalFilename()+" thành công.");return ApiResponse.success(201,message,out);}catch(IllegalArgumentException e){return ApiResponse.failure(400,false,e.getMessage(),null,"UPLOAD_ERROR");}catch(Exception e){return ApiResponse.failure(400,false,"Không thể đọc hoặc lưu tệp minh chứng.",null,"UPLOAD_ERROR");}}
    @RequestMapping(value={"/api/auth/avatar","/api/upload/avatar"},method=RequestMethod.POST) public ResponseEntity<?> avatar(@RequestParam("avatar")MultipartFile file,HttpServletRequest req){Map<String,Object>u=auth.currentUser(req);try{Map<String,Object>saved=upload.saveAvatar(file.getBytes(),first(file.getOriginalFilename(),"avatar.png"),u);users.updateProfile(Json.str(u.get("id")),UserService.map("avatar",saved.get("fileUrl")),u);return ApiResponse.success(200,"Cập nhật ảnh đại diện thành công.",UserService.map("avatar",saved.get("fileUrl"),"user",UserService.map("id",u.get("id"),"username",u.get("username"),"fullName",u.get("fullName"),"role",u.get("role"),"avatar",saved.get("fileUrl")),"fileName",saved.get("fileName"),"fileUrl",saved.get("fileUrl")));}catch(Exception e){return ApiResponse.failure(400,false,e.getMessage()==null?"Ảnh đại diện không hợp lệ.":e.getMessage(),null,"AVATAR_ERROR");}}
    @GetMapping("/api/evidence/{filename}") public ResponseEntity<?> serveEvidence(@PathVariable String filename,HttpServletRequest req){Map<String,Object>u=auth.currentUser(req);String clean=Paths.get(filename).getFileName().toString();if("STUDENT".equals(u.get("role"))){boolean owned=db.one("SELECT filename FROM evidence_uploads WHERE filename=? AND ownerid=?",clean,u.get("id"))!=null;boolean attached=false;for(Map<String,Object>c:cases.list(UserService.map("studentId",u.get("id"))))for(Object f:(List<?>)c.get("evidenceFiles")){Map<String,Object>file=Json.object(f);if(clean.equals(file.get("fileName"))||Json.str(file.get("fileUrl")).contains(clean))attached=true;}if(!owned&&!attached){audits.log("UNAUTHORIZED_FILE_ACCESS_ATTEMPT",u,UserService.map("requestedFile",clean),"BLOCKED","Sinh viên cố gắng truy cập tệp minh chứng không thuộc hồ sơ.");return ApiResponse.failure(403,false,"Bạn không có quyền truy cập tệp minh chứng này.",null,"FORBIDDEN");}}return fileResponse(clean,true);}
    @GetMapping("/api/avatar/{filename}") public ResponseEntity<?> serveAvatar(@PathVariable String filename){return fileResponse(Paths.get(filename).getFileName().toString(),false);}
    private ResponseEntity<?> fileResponse(String name,boolean evidence){try{Path path=upload.directory().resolve(name).normalize();if(!path.getParent().equals(upload.directory())||!Files.isRegularFile(path))return ApiResponse.failure(404,false,evidence?"Không tìm thấy tệp minh chứng.":"Không tìm thấy ảnh đại diện.",null,"NOT_FOUND");String type=name.toLowerCase().endsWith(".webp")?"image/webp":name.toLowerCase().endsWith(".png")?"image/png":name.toLowerCase().endsWith(".jpg")||name.toLowerCase().endsWith(".jpeg")?"image/jpeg":"application/pdf";return ResponseEntity.ok().contentType(MediaType.parseMediaType(type)).body(Files.readAllBytes(path));}catch(Exception e){return ApiResponse.failure(404,false,"Không tìm thấy tệp.",null,"NOT_FOUND");}}
    private static String first(String a,String b){return a==null||a.trim().isEmpty()?b:a;}
}
